// 顯示名稱: 近[10]年[現金股利]趨勢向下
// 執行頻率: 年
// 
// _p1參數: 
// _p1數值: 5,10,15
// _p2參數: 
// _p2數值: 0=[股利],1=[現金股利],2=[股票股利]
// 
input:_p1(10);
input:_p2(1);
SetTotalBar(_p2+2);
if CurrentBar < GetTotalBar then return;
if GetTotalBar < _p2 then return;
if _p1 = 0 and DownTrend(GetField("股利合計"), _p2) then ret=1;
if _p1 = 1 and DownTrend(GetField("現金股利"), _p2) then ret=1;
if _p1 = 2 and DownTrend(GetField("股票股利"), _p2) then ret=1;

{@type:filter}
// 腳本類型: 選股腳本
// 腳本名稱: 股利較去年成長X%以上
// 顯示名稱: [現金股利]較去年[成長10%以上]
// 執行頻率: 年
// 
// _p1參數: 
// _p1數值: 0=[股利],1=[現金股利],2=[股票股利]
// _p2參數: 
// _p2數值: 0=[成長],10=[成長10%以上],20=[成長20%以上],30=[成長30%以上],50=[成長50%以上],-0.5=[成長0.5元以上],-1=[成長1元以上],-2=[成長2元以上]
// 
{股利較前期成長X%/X元}
SetTotalBar(6);
input: _p1(1);
input: _p2(10);  { 0=成長, >0= 成長_p1% <= 成長(-p1)}
if _p2 = 0 then 
        Begin
                switch(_p1) begin
                        case 0:
                if GetField("股利合計") > GetField("股利合計")[1] then ret=1;
                        case 1:
                                if GetField("現金股利") > GetField("現金股利")[1] then ret=1;
                        case 2:
                                if GetField("股票股利") > GetField("股票股利")[1] then ret=1;
                end;
        end;

if _p2  > 0 then 
        Begin
                switch(_p1) begin
                        case 0:
                                if RateOfChange(GetField("股利合計"), 1) >= _p2 then ret=1;
                        case 1:
                                if RateOfChange(GetField("現金股利"), 1) >= _p2 then ret=1;
                        case 2:
                                if RateOfChange(GetField("股票股利"), 1) >= _p2 then ret=1;
                end;
        end;

if _p2  < 0 then 
        Begin
                switch(_p1) begin
                        case 0:
                                 if GetField("股利合計") - GetField("股利合計")[1] >= absvalue(_p2) then ret=1;
                        case 1:
                                 if GetField("股利合計") - GetField("股利合計")[1] >= absvalue(_p2) then ret=1;
                        case 2:
                                 if GetField("股利合計") - GetField("股利合計")[1] >= absvalue(_p2) then ret=1;
                end;
        end;

outputField1(GetField("股利合計"));
outputField2(GetField("股利合計")[1]);

