// _p1數值: 0=[減少],10=[減少10%以上],20=[減少20%以上],30=[減少30%以上],50=[減少50%以上]
// 
input:_p1(10); 
SetTotalBar(2);
if _p1 = 0 then begin
  if GetField("來自營運之現金流量") < GetField("來自營運之現金流量")[4] then ret=1;
end else begin
  if RateOfChange(GetField("來自營運之現金流量"), 4) <= -1*_p1 then ret=1;
end;
OutputField(1, GetField("來自營運之現金流量")*0.01);

