// 
input:_p1(10); 
SetTotalBar(2);
if _p1 = 0 then begin
  if GetField("每股自由現金流量") < GetField("每股自由現金流量")[4] then ret=1;
end else begin
  if RateOfChange(GetField("每股自由現金流量"), 4) <= -1*_p1 then ret=1;
