// _p1數值: 3,5,7,10
// _p2參數: 角度的下限值
// _p2數值: 30,60,90
// 
Input:_p1(3);
Input:_p2(30);
variable:_Side(1);
SetTotalBar(100);
value1 = getsymbolfield("TSE.TW","v")/100000000;
value2 = LinearRegAngle(value1, _p1);
If _Side * value2 > 0 and _Side * value2 > _p2 then ret = 1;

