else if _Side = -1 and UpTrend(Average(GetField("成交量"),period),10) then ret = 1;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 櫃買指數多空淨力翻多
// 顯示名稱: 櫃買指數多空淨力翻多
// 執行頻率: 日(逐筆洗價)
// 
// 
Var:period(10);//長期參數
settotalBar(12);
value1=summation(high-close,period);//上檔賣壓
value2=summation(close-open,period); //多空實績
value3=summation(close-low,period);//下檔支撐
value4=summation(open-close[1],period);//隔夜力道
if close<>0 then value5=(value2+value3+value4-value1)/close*100;
value6=linearregslope(value5,period);
ret = trueall(value6[1]<0,10) and value6>0 and value5 <0;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 櫃買指數上漲家數大於下跌家數
// 顯示名稱: 櫃買指數上漲家數 > 下跌家數
// 執行頻率: 日(逐筆洗價)
// 
// 上漲家數＝漲停家數+上漲家數
// 下跌家數＝跌停家數+下跌家數
// 
Var:_p1(1);//,"計算天數"
var:_Side(1);
settotalBar(12);
value4=summation((GetField("上漲家數")+GetField("漲停家數"))-(getfield("下跌家數")+getfield("跌停家數")),_p1);
value5=average(value4,5);
if _Side = 1 and value5>0 then 
        ret=1
else if _Side = -1 and value5<0 then 
        ret=1;

{@type:sensor}
