settotalBar(10);
value3=getfield("上漲家數")+GetField("漲停家數")+getfield("下跌家數")+GetField("跌停家數");
if value3 = 0 then value4 = 0 else value4=(getfield("上漲家數")+GetField("漲停家數"))/value3*100;
