{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 紅三兵
// 顯示名稱: 紅三兵
// 執行頻率: 1分(非逐筆洗價)
// 
// 
var:_count(0);
settotalbar(5);
if GetFieldDate("日期") <> GetFieldDate("日期")[1] then _count = 0 else _count += 1;
if        _count >= 2 then begin
        condition1=        ( close - open ) >(high -low) * 0.75;//狀況1:        實體上漲K棒
        condition2=        ( close[1] - open[1] ) >(high[1] -low[1]) * 0.75;//狀況2:        實體上漲K棒
        condition3=        ( close[2] - open[2] ) >(high[2] -low[2]) * 0.75;//狀況3:        實體上漲K棒
        condition4=        close > close[1];//狀況4:        上漲
        condition5=        close[1] > close[2];//狀況5:        上漲
end else begin
        condition1 = false;
        condition2 = false;
        condition3 = false;
        condition4 = false;
        condition5 = false;
end;
IF condition1 and condition2 and condition3 and        condition4 and condition5 THEN RET=1;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: N連陽
// 顯示名稱: 1分K出現[5]連陽
// 執行頻率: 1分(非逐筆洗價)
// 
// 連續五根紅K棒
// _p1參數: 1分鐘出現紅K次數的下限值
// _p1數值: 3,5,10
// 
Input:_p1(5);//紅K次數
variable:_Side(1);//紅K=1、黑K=-1
variable:_signal(0);

//計算當日K棒編號
variable:_barnumber(0);
_barnumber = _barnumber + 1;
var:_IsFirstCall(false);
var:intraBarPersist _firsttime(0), intraBarPersist _firstbar(0);
_IsFirstCall = false;
if _firstbar <> currentBar then begin
        _firstbar = currentBar;
        _IsFirstCall = true;
end;
if _IsFirstCall then begin
        if date <> date[1] then _barnumber = 1;
end;

//是否紅K
_signal = iff(_Side * (close-open) > 0,1,0);

condition1 = _barnumber >= _p1-1; //僅當日觸發
condition2 = summation(_signal,_p1) = _p1;
if condition1 and condition2 then ret = 1;

