value6=nthhighestbar(2,high[1],period);//第二高價距今幾根bar
value7=nthhighestbar(3,high[1],period);//第三高價距今幾根bar
settotalBar(22);
ret = value6-value5>3 
and value7-value6>3
//三個高點沒有連在一起，且是愈來愈高
