{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 上昇趨勢確立
// 顯示名稱: 上昇趨勢確立
// 執行頻率: 日(逐筆洗價)
// 
// 
var:Length(20); //"計算期間"
settotalBar(22);
LinearReg(close, Length, 0, value1, value2, value3, value4);
//做收盤價20天線性回歸
value5=rsquare(close,value4,20);//算收盤價與線性回歸值的R平方
ret = value1> 0 and value5 crosses over 0.2;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 下降趨勢結束
// 顯示名稱: 下降趨勢結束
// 執行頻率: 日(逐筆洗價)
// 
// 
Var:in1(70);
//尋找不同區間大小下目測所認為的高點。
settotalBar(100);value1=highest(H,in1);//找出一定區間的高點
if value1>value1[1] then value2=value1;//如果高點變高則保留高點，這樣做的原因是可以找到一波下降之後的高點
condition1 = value2=value2[1];//條件:保留之高點維持(階梯的平台)
condition2 = trueall(condition1,in1);//在計算區間內高點都沒有變 
if condition2 and not condition2[1] then begin
	value6=value5;
	value5=value4;
	value4=value3;
	value3=value2;
end;
condition3 = value3-value2<value4-value3 and value4-value3<value5-value4 and value5-value4<value6-value5 and value3-value2>0;//平台的高度一階比一階低
ret = condition3[1] and not condition3;//此秩序被打破時進場

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 平台三角型整理突破
// 顯示名稱: 平台三角型整理突破
// 執行頻率: 日(逐筆洗價)
// 
// 
Var: _period(15);//資料區間
Var: _range(1);//區間寬容值
Var: _side(1);//方向SIDE
variable:Kprice(0),KpriceH(0),KpriceL(0);
if GetInfo("Instance") = 2 then 
        settotalBar(15 + 10)
else
        settotalBar(3);
//起迄點有形成三角收斂
if not (high[1] <= high[_period] and low[1] >= low[_period]) then return;
//範圍內的高低點無出現突破現象
KpriceH = highest(high[1],_period);
KpriceL = lowest(low[1],_period);
Kprice = iff(_side = 1, KpriceH, KpriceL);
if not (KpriceH <= high[_period] * (1 + 0.01 * _range) and KpriceL >= low[_period] * (1 - 0.01 * _range)) then return;
value1 = iff(_side = 1, high - KpriceH, KpriceL - low);
value2 = iff(_side = 1, high[1] - KpriceH, KpriceL - low[1]);
if value1*value2 < 0 then
ret=1;

