{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: U型底
// 顯示名稱: U型底
// 執行頻率: 日(逐筆洗價)
// 
// U型底部期數為20日；連續下降趨勢天數為20日；標準差放寬倍數為5倍
// 
variable:KP(0),HSV(0);
settotalbar(250);
value1=standarddev(weightedclose,10,2);//計算一定期數(10日)標準差
value2=average(value1,250)*0.5;//計算一年(250日)標準差，標準差放寬倍數為0.5
value3=average(C,5);//MA5
value4=average(C,10);//MA10
value5=average(C,20);//MA20
if value1 crosses over value2 then begin//若標準差向上跨越一年平均標準差
        KP=0;
        HSV=0;
end;
if value1>=value2 then begin//在連續變動趨勢中
        if value1>HSV then HSV=value1;//尋找標準差最大點
        if HSV<>HSV[1] then KP=C;//將標準差最大的點之收盤價視為關鍵價
end;
condition2=value1<value2;//標準差小於年均標準差
condition3=trueall(condition2,20);//連續20期
condition4=value4<value4[1];//MA10為下降趨勢
condition5=trueall(condition4,20);//連續下降20期
condition7=trueall(not condition4,20);//連續20期不下降
if not condition5 and condition5[1] then condition6 = true;//若連續下降
if C crosses over KP and condition3 and trueall(condition6,round(20/2,0))
//若收盤價突破關鍵價且期間內標準差小於年均且下降趨勢結束一段時間
then begin
        condition6=false;
        ret=1;//買進
end;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: 碗型底
// 顯示名稱: 碗型底
// 執行頻率: 日(逐筆洗價)
// 
// 
Var:t2(60),t1(1);
settotalBar(100);
value1=(H+L+O+C)/4;
value2=square(H)+square(L)+square(O)+square(C);
value14+=value2;
if value2[t2]<>0 then value14-=value2[t2];
value15+=value1;
if value1[t2]<>0 then value15-=value1[t2];
value16=(value14-t2*4*square(value15/t2))/(t2*4);
value17=mtm(t2/2);
value18=wma(value17,round(t2*0.2,0));
value19=wma(value16,round(t2*0.2,0));
condition1=value19<value19[1] and value18>value18[1];
if value18 crosses under 0 then condition2=true;
if trueall(value19>value19[1] and value18<value18[1],t2*0.1) then condition4=true;
if (condition1 or condition3) and condition2 and condition4 then begin
	condition2=false;
	condition4=false;
	ret=1;
end;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: V型反轉
// 顯示名稱: V型反轉
// 執行頻率: 日(逐筆洗價)
// 
// 
Var:period(40);
variable:ld(0);
settotalBar(43);

ld=lowestbar(low,period);
//找出區間最低點所在的bar位置
if angle(date[period],date[ld])<-45
//區間起始點到最低點之間的角度是負的，且小於負的45度
and angle(date[ld],date)>45
//區間最低點到最近一期的角度是正的，且大於45度
and ld>=4
//最低點的位置距離現在超過三根bar以上
and close[ld]*1.3<highest(high,40)
//最低點距離兩個月來的高點跌幅超過四成
then condition1=true;
value1=barslast(condition1);
if value1[1]>60
//上一次發生這種V型反轉超過六十天
and value1=0
//今天發生V型反轉
then ret=1;

