// 顯示名稱: 淨力指標低檔回升
// 執行頻率: 日(逐筆洗價)
// 
// 
Var:period2(10);//,"長期參數"
settotalBar(12);
value12=summation(high-close,period2);//上檔賣壓
value13=summation(close-open,period2); //多空實績
value14=summation(close-low,period2);//下檔支撐
value15=summation(open-close[1],period2);//隔夜力道
if close<>0 then
        value16=(value13+value14+value15-value12)/close*100
else
        value16 = value16[1];
ret = value16 crosses over -4;

{@type:sensor}
// 腳本類型: 警示腳本
// 腳本名稱: OBV多頭排列
// 顯示名稱: OBV多頭排列
// 執行頻率: 日(逐筆洗價)
// 
// 
variable: obvolume(0);
settotalBar(12);
if CurrentBar = 1 then
	obvolume = 0
else
  begin	
	if close > close[1] then
		obvolume = obvolume[1] + volume
	else
	  begin
		if close < close[1] then
			obvolume = obvolume[1] - volume
		else
			obvolume = obvolume[1];
	  end;		
  end;
//上面先算出OBV  下面開始寫觸發條件
if 
trueall(volume>average(volume,5),3)
//成交量連三日大於5日均量
and
trueall(obvolume>average(obvolume,5),3)
//obv連三日大於5日obv
and average(obvolume,5)>average(obvolume,10)
//5日obv大於10日ovb
then ret=1;

